from pathlib import Path

p = Path('src/edumon/EdumonApp.tsx')
s = p.read_text()
s = s.replace("import type { PointerEvent as ReactPointerEvent } from 'react'\n", '')
s = s.replace("import { SharedBasicSessionPanel, useProductTeachingSession } from '../teaching/session'", "import { SharedBasicSessionPanel, deriveAlarmSessionSemantics, useProductTeachingSession, useTeachingAlarmSync } from '../teaching/session'")
s = s.replace("import { listProductScenarios, type ProductScenarioRow } from '../teaching/scenario/productLibrary'", "import { createProductScenario, deleteProductScenario, listProductScenarios, updateProductScenario, type ProductScenarioRow } from '../teaching/scenario/productLibrary'\nimport { TeachingLaserPointerSurface, useScenarioLibraryManager, useTeachingDisplaySync } from '../teaching'")
s = s.replace('className={`edumon-trace edumon-trace-${spec.className}`}', 'className={`edumon-trace edumon-trace-${spec.className} waveform-card`}')
s = s.replace('<div className="edumon-trace-label"><strong>{spec.label}</strong>{spec.unit && <span>{spec.unit}</span>}</div>', '<div className="edumon-trace-label waveform-label"><strong>{spec.label}</strong>{spec.unit && <span>{spec.unit}</span>}</div>')
s = s.replace('<div className={`edumon-value-panel edumon-value-${className}`}>\n      <div className="edumon-value-label">{label}</div>\n      <div className="edumon-value-main">{value}</div>\n      {unit && <div className="edumon-value-unit">{unit}</div>}\n      {detail && <div className="edumon-value-detail">{detail}</div>}\n    </div>', '<div className={`edumon-value-panel edumon-value-${className} metric`}>\n      <span className="edumon-value-label">{label}</span>\n      <strong className="edumon-value-main">{value}</strong>\n      {unit && <small className="edumon-value-unit">{unit}</small>}\n      {detail && <div className="edumon-value-detail">{detail}</div>}\n    </div>')
s = s.replace("  const [laserPoint, setLaserPoint] = useState({ x: 0.5, y: 0.25 })\n", '')
s = s.replace("  const [savedScenarios, setSavedScenarios] = useState<Array<ProductScenarioRow<EdumonStoredScenario>>>([])\n", '')
s = s.replace("  const [savedScenariosBusy, setSavedScenariosBusy] = useState(false)\n  const [savedScenarioMessage, setSavedScenarioMessage] = useState<string | null>(null)\n", '')
old = "  const scenarioProduct = scenarioProductForEdumonModule(module.id)\n  const edumonScenarioAdapter = useMemo(() => createEdumonScenarioRuntimeAdapter((snapshot) => {"
new = "  const scenarioProduct = scenarioProductForEdumonModule(module.id)\n  const scenarioLibraryRepository = useMemo(() => ({\n    list: () => listProductScenarios<EdumonStoredScenario>(scenarioProduct),\n    create: (name: string, scenario: EdumonStoredScenario) => createProductScenario(scenarioProduct, name, scenario),\n    update: (id: string, updates: { name?: string; scenario?: EdumonStoredScenario }) => updateProductScenario(scenarioProduct, id, updates),\n    remove: (id: string) => deleteProductScenario(scenarioProduct, id),\n  }), [scenarioProduct])\n  const scenarioLibrary = useScenarioLibraryManager<ProductScenarioRow<EdumonStoredScenario>, EdumonStoredScenario>({ enabled: instructorAuthenticated, repository: scenarioLibraryRepository })\n  const savedScenarios = scenarioLibrary.items\n  const savedScenariosBusy = scenarioLibrary.busy\n  const savedScenarioMessage = scenarioLibrary.message ?? (!savedScenariosBusy && instructorAuthenticated && !savedScenarios.length ? 'No saved scenarios for this simulator yet. Create one in Scenario Builder.' : null)\n  useEffect(() => { setSelectedSavedScenarioId((current) => savedScenarios.some((row) => row.id === current) ? current : (savedScenarios[0]?.id ?? '')) }, [savedScenarios])\n\n  const displaySync = useTeachingDisplaySync(teachingSession.role, teachingSession.session?.id ?? null, {\n    localLaserEnabled: laserActive,\n    onCandidateFrozenChange: (active) => { setFrozen(active); setFrozenSamples(active ? liveSamples : null) },\n    onCandidateLaserChange: setLaserActive,\n  })\n  const alarmSemantics = deriveAlarmSessionSemantics(teachingSession.role, { syncAlarms: true, candidateCanEditAlarms: false, alarmsSilent: false })\n  const alarmSync = useTeachingAlarmSync(teachingSession.role, teachingSession.session?.id ?? null, (next) => { setAlarmSilencedUntil(next.silenceUntil) })\n\n  const edumonScenarioAdapter = useMemo(() => createEdumonScenarioRuntimeAdapter((snapshot) => {"
s = s.replace(old, new)
start = s.find('  const refreshSavedScenarios = async () => {')
if start != -1:
    end = s.find('  const loadSavedScenario = async (id: string) => {', start)
    s = s[:start] + s[end:]
s = s.replace("  const toggleFreeze = () => {\n    if (frozen) {\n      setFrozen(false)\n      setFrozenSamples(null)\n      return\n    }\n    setFrozenSamples(liveSamples)\n    setFrozen(true)\n  }", "  const toggleFreeze = () => {\n    if (teachingSession.role === 'candidate' && displaySync.state.frozen) return\n    const next = !frozen\n    setFrozen(next)\n    setFrozenSamples(next ? liveSamples : null)\n    if (teachingSession.role === 'instructor' && teachingSession.session?.id) displaySync.setFrozen(next)\n  }")
s = s.replace("      if (next && !frozen) {\n        setFrozenSamples(liveSamples)\n        setFrozen(true)\n      }\n      return next", "      if (next && !frozen) {\n        setFrozenSamples(liveSamples)\n        setFrozen(true)\n        if (teachingSession.role === 'instructor' && teachingSession.session?.id) displaySync.setFrozen(true)\n      }\n      if (teachingSession.role === 'instructor' && teachingSession.session?.id) displaySync.setLaserEnabled(next)\n      return next")
s = s.replace("  const silenceAlarm = (durationMs: number) => {\n    if (alarmSilenceTimeoutRef.current != null) window.clearTimeout(alarmSilenceTimeoutRef.current)", "  const silenceAlarm = (durationMs: number) => {\n    if (alarmSemantics.candidateLocked) return\n    if (teachingSession.role === 'instructor' && teachingSession.session?.id) alarmSync.silenceFor(durationMs)\n    if (alarmSilenceTimeoutRef.current != null) window.clearTimeout(alarmSilenceTimeoutRef.current)")
start = s.find('  const handleLaserMove = (event: ReactPointerEvent<HTMLDivElement>) => {')
if start != -1:
    end = s.find('\n  const alarmMinutes', start)
    s = s[:start] + s[end:]
s = s.replace('className="edumon-waveform-area" onPointerMove={handleLaserMove} onPointerDown={handleLaserMove}', 'className="edumon-waveform-area waveforms"')
s = s.replace('className="edumon-measurements"', 'className="edumon-measurements metrics-panel"')
s = s.replace("              {laserActive && <div className=\"edumon-laser-point\" style={{ left: `${laserPoint.x * 100}%`, top: `${laserPoint.y * 100}%` }} aria-hidden=\"true\" />}\n", '')
s = s.replace('            </aside>\n          </div>', '            </aside>\n            <TeachingLaserPointerSurface role={teachingSession.role} sessionId={teachingSession.session?.id ?? null} enabled={laserActive} onEnabledChange={setLaserActive} />\n          </div>', 1)
s = s.replace("            laserActive={laserActive}\n            onLaserToggle={toggleLaser}\n            frozen={frozen}\n            onFreezeToggle={toggleFreeze}\n            alarmSilenced={alarmSilenceRemaining > 0}", "            laserActive={laserActive}\n            onLaserToggle={toggleLaser}\n            laserDisabled={candidateLocked}\n            frozen={frozen}\n            onFreezeToggle={toggleFreeze}\n            freezeDisabled={teachingSession.role === 'candidate' && displaySync.state.frozen}\n            alarmSilenced={alarmSilenceRemaining > 0}\n            alarmDisabled={alarmSemantics.candidateLocked}")
p.write_text(s)

p = Path('src/session/useTeachingSession.ts')
s = p.read_text()
s = s.replace("import { useSharedTeachingSession, type SharedTeachingRole, type RecoverableTeachingCandidate, type SharedTeachingRuntimeTransport } from '../teaching/session'", "import { deriveAlarmSessionSemantics, useSharedTeachingSession, type SharedTeachingRole, type RecoverableTeachingCandidate, type SharedTeachingRuntimeTransport } from '../teaching/session'")
s = s.replace("  const candidateAlarmsLocked = role === 'candidate' && Boolean(session?.sync_alarms) && !Boolean(session?.candidate_can_edit_alarms)\n  const candidateAlarmsSilent = role === 'candidate' && Boolean(session?.sync_alarms) && Boolean(session?.alarms_silent)", "  const alarmSemantics = deriveAlarmSessionSemantics(role, { syncAlarms: Boolean(session?.sync_alarms), candidateCanEditAlarms: Boolean(session?.candidate_can_edit_alarms), alarmsSilent: Boolean(session?.alarms_silent) })\n  const candidateAlarmsLocked = alarmSemantics.candidateLocked\n  const candidateAlarmsSilent = alarmSemantics.forcedSilent")
p.write_text(s)

p = Path('src/components/InstructorAccountControls.tsx')
s = p.read_text()
s = s.replace("import { eduventTeachingHost, useTeachingPrompts } from '../teaching'", "import { eduventTeachingHost, useScenarioLibraryManager, useTeachingPrompts } from '../teaching'")
s = s.replace("  const [presets, setPresets] = useState<InstructorPresetRow[]>([])\n", "  const scenarioLibraryRepository = useMemo(() => ({ list: () => listInstructorPresets(), create: (name: string, scenario: InstructorScenarioSnapshot) => createInstructorPreset(name, scenario), update: (id: string, updates: { name?: string; scenario?: InstructorScenarioSnapshot }) => updateInstructorPreset(id, updates), remove: (id: string) => deleteInstructorPreset(id) }), [])\n  const scenarioLibrary = useScenarioLibraryManager<InstructorPresetRow, InstructorScenarioSnapshot>({ enabled: Boolean(account), repository: scenarioLibraryRepository })\n  const presets = scenarioLibrary.items\n")
old = "  const refreshPresets = async (nextAccount: User | null = account) => {\n    if (!nextAccount) {\n      setPresets([])\n      return\n    }\n    try {\n      setPresets(await listInstructorPresets())\n    } catch (cause) {\n      setPresetMessage(cause instanceof Error ? cause.message : 'Unable to load instructor scenarios.')\n    }\n  }\n\n  useEffect(() => {\n    if (account) void refreshPresets(account)\n    else setPresets([])\n  }, [account])\n"
s = s.replace(old, "  const refreshPresets = async (_nextAccount: User | null = account) => { await scenarioLibrary.refresh() }\n\n  useEffect(() => { if (scenarioLibrary.message) setPresetMessage(scenarioLibrary.message) }, [scenarioLibrary.message])\n")
p.write_text(s)
